# Standard library
import uuid
from datetime import datetime

# Third-party
from geoalchemy2 import Geometry
from sqlalchemy import DateTime, ForeignKey, Integer, Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, TimestampMixin


class ExplorerSubWaypoint(TimestampMixin, Base):
    __tablename__ = "explorer_sub_waypoint"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the "
            "database using gen_random_uuid()."
        ),
    )
    name: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "Display name of the waypoint, such as "
            "'Rest Stop' or 'Summit Viewpoint'."
        ),
    )
    summary: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "Short summary text describing this "
            "waypoint, used in list views and "
            "map popups."
        ),
    )
    description: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "Long-form description of this waypoint "
            "with details about the stop, used in "
            "detail views."
        ),
    )
    location = mapped_column(
        Geometry("POINT", srid=4326),
        nullable=True,
        description=(
            "PostGIS Point geometry (SRID 4326) "
            "marking the geographic position of "
            "this waypoint."
        ),
    )
    altitude_m: Mapped[int | None] = mapped_column(
        Integer,
        description=("Altitude of this waypoint above sea level in meters."),
    )
    arrived_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        description=(
            "Timezone-aware UTC timestamp of when the "
            "user arrived at this waypoint."
        ),
    )
    departed_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        description=(
            "Timezone-aware UTC timestamp of when the "
            "user departed from this waypoint."
        ),
    )
    duration_min: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Time spent at this waypoint in minutes, "
            "calculated from arrived_at and "
            "departed_at."
        ),
    )
    poi_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("compendium_cat_poi.id"),
        description=(
            "FK to compendium_cat_poi. Links this "
            "waypoint to a known Point of Interest "
            "from the compendium."
        ),
    )
